Json Parse(const std::string& text) {
 std::vector<std::set<std::string>> keys;
 return Json::parse(text,[&](int,Json::parse_event_t e,Json& v){
  if(e==Json::parse_event_t::object_start)keys.emplace_back();
  if(e==Json::parse_event_t::key)Require(keys.back().insert(v.get<std::string>()).second,"Duplicate JSON key");
  if(e==Json::parse_event_t::object_end)keys.pop_back();return true;});
}
ULong64_t UInt(const Json& o,const std::string& k,ULong64_t max=std::numeric_limits<ULong64_t>::max()) {
 const auto& v=o.at(k);Require(v.is_number_integer(),"Expected JSON integer: "+k);
 if(!v.is_number_unsigned())Require(v.get<Json::number_integer_t>()>=0,"Negative JSON integer: "+k);
 auto n=v.get<Json::number_unsigned_t>();Require(n<=max,"JSON integer out of range: "+k);return n;
}
void Unique(TFile& f){std::set<std::string> keys;TIter next(f.GetListOfKeys());while(auto* k=next())Require(keys.insert(k->GetName()).second,"Duplicate ROOT key/cycle");}
std::string TextSafe(TFile& f,const char* key){auto s=Text(f,key);auto* raw=dynamic_cast<TObjString*>(f.Get(key));Require(raw&&std::size_t(raw->GetString().Length())==s.size(),"Embedded NUL metadata string");return s;}
bool Close(double a,double b){return std::abs(a-b)<=1e-9+1e-10*std::max(std::abs(a),std::abs(b));}
ULong64_t Add(ULong64_t a,ULong64_t b){Require(b<=std::numeric_limits<ULong64_t>::max()-a,"Counter overflow");return a+b;}
