class Gaussian {std::mt19937_64 engine;public:ULong64_t draws=0;explicit Gaussian(ULong64_t seed):engine(seed){}float operator()(){double a=(double(engine()>>12)+.5)*0x1.0p-52,b=(double(engine()>>12)+.5)*0x1.0p-52;++draws;return Real(std::sqrt(-2*std::log(a))*std::cos(6.2831853071795864769*b));}};
